/**
 * Render official Norden icon (viewBox: 0 0 697 697)
 */
export function renderNordenIconSvg(x: number, y: number, size: number): string {
  const scale = size / 697;
  return `<g transform="translate(${x}, ${y}) scale(${scale})">${NORDEN_ICON_PATHS}</g>`;
}

/**
 * Render official Norden horizontal logo (viewBox: 0 0 523 191)
 */
export function renderNordenHorizontalSvg(x: number, y: number, width: number): string {
  const scale = width / 523;
  return `<g transform="translate(${x}, ${y}) scale(${scale})">${NORDEN_HORIZONTAL_PATHS}</g>`;
}
